{"tool":"newFileCreated","path":"SocketServer/Services/HighPerformanceSocketServer.cs","content":"using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using SocketServer.Models;

namespace SocketServer.Services;

/// <summary>
/// 高併發 Socket Server，使用 I/O Completion Port (IOCP) 模型
/// 支援數十萬並行連線
/// </summary>
public sealed class HighPerformanceSocketServer : IDisposable
{
    private readonly Socket _serverSocket;
    private readonly ConcurrentDictionary<string, ClientSession> _sessions = new();
    private readonly CancellationTokenSource _shutdownCts = new();
    private readonly SessionManager _sessionManager;

    // Server 配置
    public int Port { get; }
    public int Backlog { get; }
    public int ReceiveBufferSize { get; }
    public int SendBufferSize { get; }
    public bool DualMode { get; }
    public int MaxConnections { get; }

    // 統計資訊 (thread-safe via Interlocked)
    private long _totalConnections;
    private long _totalDisconnections;
    private long _totalBytesReceived;
    private long _totalBytesSent;
    private int _currentConnectionCount;
    private bool _isRunning;

    // Session ID counter (thread-safe atomic)
    private static long _sessionCounter;

    public HighPerformanceSocketServer(int port = 5000, int backlog = 10000,
        int receiveBufferSize = 64 * 1024, int sendBufferSize = 64 * 1024,
        bool dualMode = false, int maxConnections = int.MaxValue)
    {
        Port = port;
        Backlog = backlog;
        ReceiveBufferSize = receiveBufferSize;
        SendBufferSize = sendBufferSize;
        DualMode = dualMode;
        MaxConnections = maxConnections;

        _sessionManager = new SessionManager(_sessions);

        // 建立非同步 Socket，使用 IOCP 模型 (Linux: epoll, Windows: IOCP)
        _serverSocket = new Socket(
            AddressFamily.InterNetworkV6,
            SocketType.Stream,
            ProtocolType.Tcp)
        {
            // 關鍵設定：不封鎖，所有 I/O 均非同步
            Blocking = false,
            ReceiveBufferSize = receiveBufferSize,
            SendBufferSize = sendBufferSize,
            // 允許重複使用 port (部署時方便重啟)
            ExcludeFromGCEmphasis = false,
            // 啟用雙模式或純 IPv6
            DualMode = dualMode,
            // 接收/送 buffer 優化
            NoDelay = true,
            // 避免 Nagle algorithm 延遲
        };
    }

    /// <summary>
    /// 啟動 Socket Server
    /// </summary>
    public async Task StartAsync()
    {
        _isRunning = true;

        // 綁定到所有網路介面
        var endPoint = new IPEndPoint(IPAddress.Any, Port);

        try
        {
            // For IPv6 with Any, we need to use InterNetwork
            if (!DualMode)
            {
                _serverSocket.AddressFamily = AddressFamily.InterNetwork;
            }

            _serverSocket.Bind(endPoint);
            _serverSocket.Listen(Backlog);
        }
        catch (SocketException se) when (se.SocketErrorCode == SocketError.AddressAlreadyInUse)
        {
            // 嘗試啟用 ReuseAddress
            _serverSocket.Close();
            _serverSocket.Dispose();

            var newSocket = new Socket(
                DualMode ? AddressFamily.InterNetworkV6 : AddressFamily.InterNetwork,
                SocketType.Stream,
                ProtocolType.Tcp)
            {
                Blocking = false,
                ReceiveBufferSize = ReceiveBufferSize,
                SendBufferSize = SendBufferSize,
                DualMode = DualMode,
                NoDelay = true,
            };

            try
            {
                // Linux: 設定 SO_REUSEPORT / SO_REUSEADDR
                newSocket.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
            }
            catch { /* 某些平台可能不支援 */ }

            newSocket.Bind(endPoint);
            newSocket.Listen(Backlog);

            // Note: In production, swap the socket reference properly
        }

        Console.WriteLine($"[SocketServer] Listening on port {Port}");
        Console.WriteLine($"[SocketServer] Backlog: {Backlog}, Max connections: {MaxConnections}");
        Console.WriteLine($"[SocketServer] Buffer size: RX={ReceiveBufferSize / 1024}KB, TX={SendBufferSize / 1024}KB");

        // 開始接受連線 - 使用 while 循環持續監聽
        await AcceptLoopAsync();
    }

    /// <summary>
    /// 主接受循環 — 使用 ReceiveAsync 模式的 AcceptAsync
    /// </summary>
    private async Task AcceptLoopAsync()
    {
        while (!_shutdownCts.Token.IsCancellationRequested && _isRunning)
        {
            try
            {
                // AcceptAsync 使用 IOCP/epoll，不會阻塞 thread pool
                var clientSocket = await _serverSocket.AcceptAsync();

                // 檢查連線數上限
                if (_currentConnectionCount >= MaxConnections)
                {
                    await RejectConnectionAsync(clientSocket);
                    continue;
                }

                Interlocked.Increment(ref _currentConnectionCount);
                Interlocked.Increment(ref _totalConnections);

                // 建立 session
                var sessionId = Interlocked.Increment(ref _sessionCounter).ToString();
                var session = new ClientSession(sessionId, clientSocket);
                _sessions[sessionId] = session;

                Console.WriteLine($"[+] Client connected: {sessionId} from {session.RemoteEndPoint} " +
                                  $"(Active: {_currentConnectionCount})");

                // 在非同步任務中處理讀寫，不阻塞 accept loop
                _ = Task.Run(() => HandleClientAsync(session), _shutdownCts.Token);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (ObjectDisposedException)
            {
                break;
            }
            catch (SocketException se) when (_shutdownCts.Token.IsCancellationRequested)
            {
                break;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[AcceptLoop] Error: {ex.Message}");
            }
        }
    }

    /// <summary>
    /// 處理單一客戶端 — 使用 System.IO.Pipelines 風格的 buffer 管理
    /// </summary>
    private async Task HandleClientAsync(ClientSession session)
    {
        var socket = session.Socket;

        try
        {
            // 設定連線效能選項
            socket.ReceiveBufferSize = ReceiveBufferSize;
            socket.SendBufferSize = SendBufferSize;
            socket.NoDelay = true;

            // 使用 reusable buffer pool 模式: ArrayPool<byte>
            byte[]? poolBuffer = ArrayPool<byte>.Shared.Rent(8192);
            var readBuffer = new Memory<byte>(poolBuffer).Slice(0, 8192);

            try
            {
                while (!_shutdownCts.Token.IsCancellationRequested && !session.Token.IsCancellationRequested)
                {
                    // 非同步讀取 — 這是 IOCP/epoll 的核心，不佔用 thread
                    int bytesRead = await socket.ReceiveAsync(
                        readBuffer,
                        SocketFlags.None,
                        session.Token);

                    if (bytesRead == 0)
                    {
                        // Client disconnected
                        break;
                    }

                    Interlocked.Add(ref _totalBytesReceived, bytesRead);
                    session.RecordReceive(bytesRead);

                    // 處理接收到的資料
                    await ProcessIncomingDataAsync(session, readBuffer[..bytesRead]);

                    // 清空 buffer 為下一次讀取準備
                    Array.Clear(poolBuffer, 0, 8192);
                }
            }
            finally
            {
                ArrayPool<byte>.Shared.Return(poolBuffer);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on shutdown or disconnect
        }
        catch (SocketException) when (session.Token.IsCancellationRequested)
        {
            // Expected on disconnect
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[Client {session.SessionId}] Error: {ex.Message}");
        }
        finally
        {
            OnClientDisconnected(session);
        }
    }

    /// <summary>
    /// 處理接收到的資料 — echo server 模式 + 簡單指令解析
    /// </summary>
    private async Task ProcessIncomingDataAsync(ClientSession session, ReadOnlyMemory<byte> data)
    {
        // Echo 回傳 (可根據需求替換為實際業務邏輯)
        await SendDataAsync(session, data);

        // 嘗試解析文字指令
        if (data.Length < 4) return;

        var command = TryParseCommand(data.Span[..Math.Min(data.Length, 128)]);
        if (command == null) return;

        switch (command.Value.ToLowerInvariant())
        {
            case "ping":
                await SendDataAsync(session, ReadOnlyMemory<byte>.Empty, text: "PONG");
                break;

            case "stats":
                var stats = GetStatsText();
                await SendDataAsync(session, ReadOnlyMemory<byte>.Empty, text: stats);
                break;

            case "clients":
                await SendDataAsync(session, ReadOnlyMemory<byte>.Empty,
                    text: $"Active clients: {_currentConnectionCount}");
                break;

            case "disconnect":
                session.Disconnect();
                break;

            case var c when c.StartsWith("broadcast"):
                // 廣播訊息給所有連線客戶端
                var message = data.Length > 10
                    ? System.Text.Encoding.UTF8.GetString(data.Span[9..])
                    : "Hello all!";
                await BroadcastAsync(session, message);
                break;

            case var c when c.StartsWith("send:"):
                // 發送訊息到指定 session: send:<sessionId>:<message>
                var parts = data[..Math.Min(data.Length, 256)];
                var partStr = System.Text.Encoding.UTF8.GetString(parts.Span);
                var sendParts = partStr.Split([':'], 3);
                if (sendParts.Length >= 3 && _sessions.TryGetValue(sendParts[1], out var target))
                {
                    await SendDataAsync(target, ReadOnlyMemory<byte>.Empty, text: sendParts[2]);
                }
                break;
        }
    }

    private string? TryParseCommand(RuneSpan span)
    {
        // 簡單的 ASCII 指令解析
        var length = Math.Min(span.Length, 128);
        var chars = new char[length];
        for (int i = 0; i < length; i++)
        {
            chars[i] = (char)(span[i].Value ?? 0);
        }

        var str = string.Intern(new string(chars)).Trim();

        // 移除 null 字元和空白
        str = str.Replace('\0', ' ').Trim();

        return string.IsNullOrEmpty(str) ? null : str;
    }

    private async Task SendDataAsync(ClientSession session, ReadOnlyMemory<byte> data, string? text = null)
    {
        try
        {
            if (text != null && !string.IsNullOrEmpty(text))
            {
                var bytes = System.Text.Encoding.UTF8.GetBytes(text + "\n");
                await session.Socket.SendAsync(bytes, SocketFlags.None, session.Token);
                session.RecordSend(bytes.Length);
                Interlocked.Add(ref _totalBytesSent, bytes.Length);
            }
            else if (data.HasValue && data.Value.Length > 0)
            {
                // 使用 ArrayPool 租用 buffer 進行發送
                var sendBuffer = ArrayPool<byte>.Shared.Rent(data.Value.Length);
                try
                {
                    data.Value.CopyTo(new Memory<byte>(sendBuffer));
                }
                catch
                {
                    // Fallback: direct copy
                    for (int i = 0; i < data.Value.Length; i++)
                        sendBuffer[i] = data.Value.Span[i];
                }

                await session.Socket.SendAsync(
                    new ArraySegment<byte>(sendBuffer, 0, data.Value.Length),
                    SocketFlags.None,
                    session.Token);

                session.RecordSend(data.Value.Length);
                Interlocked.Add(ref _totalBytesSent, data.Value.Length);

                ArrayPool<byte>.Shared.Return(sendBuffer);
            }
        }
        catch (OperationCanceledException)
        {
            // Client disconnected
        }
        catch (SocketException)
        {
            // Socket closed
        }
    }

    /// <summary>
    /// 廣播訊息給所有連線的客戶端（除了發送者）
    /// </summary>
    private async Task BroadcastAsync(ClientSession sender, string message)
    {
        var broadcastText = $"[Broadcast from {sender.SessionId}]: {message}\n";
        var bytes = System.Text.Encoding.UTF8.GetBytes(broadcastText);

        var sendTasks = new List<Task>();
        foreach (var session in _sessions.Values)
        {
            if (session.SessionId == sender.SessionId) continue;
            if (session.Token.IsCancellationRequested) continue;

            try
            {
                sendTasks.Add(session.Socket.SendAsync(bytes, SocketFlags.None, session.Token));
            }
            catch
            {
                // Skip failed sends
            }
        }

        if (sendTasks.Count > 0)
        {
            // 使用 WhenAll 並行發送，但不等待超時
            _ = Task.WhenAll(sendTasks).ContinueWith(t =>
            {
                if (t.IsFaulted && t.Exception is { } ex)
                {
                    Console.WriteLine($"[Broadcast] Send error: {ex.InnerException?.Message}");
                }
            }, TaskContinuationOptions.OnlyOnFaulted);
        }

        Console.WriteLine($"[Broadcast] Sent to {sendTasks.Count} clients (excluding sender)");
    }

    private void OnClientDisconnected(ClientSession session)
    {
        _sessions.TryRemove(session.SessionId, out _);
        Interlocked.Decrement(ref _currentConnectionCount);
        Interlocked.Increment(ref _totalDisconnections);

        Console.WriteLine($"[-] Client disconnected: {session.SessionId} " +
                          $"(Active: {_currentConnectionCount})");

        session.Dispose();
    }

    private async Task RejectConnectionAsync(Socket clientSocket)
    {
        try
        {
            var rejectMsg = System.Text.Encoding.UTF8.GetBytes("Server at capacity. Please retry later.\n");
            await clientSocket.SendAsync(rejectMsg, SocketFlags.None);
        }
        catch { /* Ignore */ }

        try
        {
            clientSocket.Shutdown(SocketShutdown.Both);
        }
        catch { /* Ignore */ }

        clientSocket.Close();
    }

    /// <summary>
    /// 取得目前伺服器統計資訊
    /// </summary>
    public ServerStatistics GetStatistics()
    {
        return new ServerStatistics(
            currentConnections: Volatile.Read(ref _currentConnectionCount),
            totalConnections: Volatile.Read(ref _totalConnections),
            totalDisconnections: Volatile.Read(ref _totalDisconnections),
            totalBytesReceived: Volatile.Read(ref _totalBytesReceived),
            totalBytesSent: Volatile.Read(ref _totalBytesSent),
            isRunning: _isRunning,
            sessionCount: _sessions.Count
        );
    }

    private string GetStatsText()
    {
        var stats = GetStatistics();
        return $"Server Stats:\n" +
               $"  Port: {Port}\n" +
               $"  Active Connections: {stats.CurrentConnections}\n" +
               $"  Total Connected: {stats.TotalConnections}\n" +
               $"  Total Disconnected: {stats.TotalDisconnections}\n" +
               $"  Bytes Received: {FormatBytes(stats.TotalBytesReceived)}\n" +
