/// </summary>
public sealed class SessionManager
{
    private readonly ConcurrentDictionary<string, ClientSession> _sessions;

    public SessionManager(ConcurrentDictionary<string, ClientSession> sessions)
    {
        _sessions = sessions;
    }

    public ClientSession? GetSession(string sessionId) => _sessions.TryGetValue(sessionId, out var s) ? s : null;
    public IEnumerable<ClientSession> GetAllSessions() => _sessions.Values;
    public int Count => _sessions.Count;
    public bool TryRemove(string sessionId) => _sessions.TryRemove(sessionId, out _);
}

/// <summary>
/// 伺服器統計資料記錄
/// </summary>
public sealed class ServerStatistics
{
    public int CurrentConnections { get; init; }
    public long TotalConnections { get; init; }
    public long TotalDisconnections { get; init; }
    public long TotalBytesReceived { get; init; }
    public long TotalBytesSent { get; init; }
    public bool IsRunning { get; init; }
    public int SessionCount { get; init; }

    public override string ToString()
    {
        return $"Connections: {CurrentConnections}, Total: {TotalConnections}, " +
