{
    Console.Error.WriteLine($"Connection error: {ex.Message}");
    Environment.Exit(1);
}

static async Task SendAndReceiveAsync(NetworkStream stream, string command)
{
    var data = Encoding.UTF8.GetBytes(command);
    await stream.WriteAsync(data);

    // 接收回應 (最多 64KB)
    var responseBuffer = new byte[65536];
    var totalBytes = 0;

    using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(5));
    try
    {
        while (totalBytes < responseBuffer.Length && !cts.Token.IsCancellationRequested)
        {
            // 使用 DataAvailable 檢查是否有資料
            if (!stream.DataAvailable)
            {
                await Task.Delay(10, cts.Token);
                continue;
            }

            var bytesRead = await stream.ReadAsync(
                responseBuffer, totalBytes, responseBuffer.Length - totalBytes, cts.Token);

            if (bytesRead == 0) break; // Server closed connection
            totalBytes += bytesRead;
        }
    }
    catch (OperationCanceledException) { /* Timeout */ }

    var response = Encoding.UTF8.GetString(responseBuffer, 0, totalBytes);
    Console.WriteLine("[Response]:");
    Console.Write(response);
}

static async Task InteractiveModeAsync(NetworkStream stream)
{
    Console.WriteLine("Interactive mode. Type 'quit' to exit.");
    Console.WriteLine("Available commands: ping, stats, clients, disconnect");

    // 啟動背景任務持續接收資料
    var receivedData = new StringBuilder();
    var receiveCts = new CancellationTokenSource();

    var receiveTask = Task.Run(async () =>
    {
        var buffer = new byte[8192];
        try
        {
            while (!receiveCts.Token.IsCancellationRequested)
            {
                if (!stream.DataAvailable)
                {
                    await Task.Delay(50, receiveCts.Token);
                    continue;
                }

                var bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length, receiveCts.Token);
                if (bytesRead == 0)
                {
                    Console.WriteLine("\n[Server disconnected]");
                    Environment.Exit(0);
                }

                lock (receivedData)
                {
                    receivedData.Append(Encoding.UTF8.GetString(buffer, 0, bytesRead));
                }
            }
        }
        catch (OperationCanceledException) { /* Expected */ }
        catch { /* Ignore */ }
    });

    try
    {
        while (true)
        {
            Console.Write("\n> ");
            var input = Console.ReadLine();

            // 輸出累積的回應
            lock (receivedData)
            {
                if (receivedData.Length > 0)
                {
                    Console.Write(receivedData.ToString());
                    receivedData.Clear();
                }
            }

            if (string.IsNullOrEmpty(input)) continue;

            if (input.Trim().ToLowerInvariant() == "quit")
            {
                break;
            }

            var data = Encoding.UTF8.GetBytes(input);
            await stream.WriteAsync(data);
        }
    }
    finally
    {
        receiveCts.Cancel();
        await receiveTask;
    }
