public sealed class ServerNode
{
    public string NodeId { get; }
    public string Host { get; }
    public int Port { get; }
    public string? Region { get; }
    public bool Enabled { get; private set; }

    // Runtime state (thread-safe)
    private NodeStatus _status;
    private int _activeConnections;
    private DateTime _lastHealthCheck;
    private DateTime _lastSuccessfulCheck;
    private int _consecutiveFailures;

    public NodeStatus Status => Volatile.Read(ref _status);
    public int ActiveConnections => Volatile.Read(ref _activeConnections);
    public DateTime LastHealthCheck => Volatile.Read(ref _lastHealthCheck);
    public DateTime LastSuccessfulCheck => Volatile.Read(ref _lastSuccessfulCheck);
    public int ConsecutiveFailures => Volatile.Read(ref _consecutiveFailures);

    public bool IsAvailable => Status == NodeStatus.Healthy && Enabled;

    public ServerNode(string nodeId, string host, int port, string? region = null)
    {
        NodeId = nodeId;
        Host = host;
        Port = port;
        Region = region;
        Enabled = true;
        _status = NodeStatus.Unknown;
        _lastSuccessfulCheck = DateTime.UtcNow;
    }

    public void MarkHealthy()
    {
        Volatile.Write(ref _status, NodeStatus.Healthy);
        Volatile.Write(ref _lastSuccessfulCheck, DateTime.UtcNow);
        Volatile.Write(ref _consecutiveFailures, 0);
    }

    public void MarkUnhealthy()
    {
        Volatile.Write(ref _status, NodeStatus.Unhealthy);
        Interlocked.Increment(ref _consecutiveFailures);
    }

    public void SetStatus(NodeStatus status)
    {
        Volatile.Write(ref _status, status);
        Volatile.Write(ref _lastHealthCheck, DateTime.UtcNow);
    }

    public void Enable() => Enabled = true;
    public void Disable() => Enabled = false;

    public int AddConnection() => Interlocked.Increment(ref _activeConnections);
    public int RemoveConnection() => Math.Max(0, Interlocked.Decrement(ref _activeConnections));

    public override string ToString() => $"{NodeId} ({Host}:{Port}) [{Status}] conns={ActiveConnections}";
