    {
        e.Cancel = true;
        cts.Cancel();
    };

    try
    {
        await gateway.StartAsync();

        // Wait until shutdown signal
        while (!cts.Token.IsCancellationRequested)
        {
            using var delayTcs = new TaskCompletionSource();
