206 | static async Task<ClientResult> ClientWorkerAsync(
207 |     int clientId, string host, int port, int durationSec,
208 |     ClientType type, AdvancedTestStats stats)
209 | {
210 |     var result = new ClientResult { Id = clientId, ClientType = type };
211 | 
212 |     try
213 |     {
214 |         using var client = new TcpSocketClient(host, port);
215 | 
216 |         var connectSw = System.Diagnostics.Stopwatch.StartNew();
217 |         await Task.WhenAny(
218 |             client.ConnectAsync(),
219 |             Task.Delay(5000) // 5s connect timeout
220 |         );
221 |         connectSw.Stop();
222 | 
223 |         if (!client.IsConnected)
224 |         {
225 |             result.ConnectSuccess = false;
226 |             result.ErrorMessage = "Connection timed out after 5s";
227 |             result.TypeLabel = type.ToString();
228 |             return result;
229 |         }
230 | 
231 |         result.ConnectSuccess = true;
232 |         result.ConnectTimeMs = connectSw.Elapsed.TotalMilliseconds;
233 |         stats.RecordConnect(connectSw.Elapsed.TotalMilliseconds);
234 | 
235 |         var rng = new Random(clientId * 31 + 7); // deterministic per client
236 |         long receiveBytes = 0;
237 | 
238 |         client.DataReceived += (text) =>
239 |         {
240 |             Interlocked.Add(ref receiveBytes, Encoding.UTF8.GetByteCount(text));
241 |         };
242 | 
243 |         var sendCount = 0;
244 |         var errorCount = 0;
245 |         long bytesSentAccum = 0;
246 | 
247 |         var endTime = DateTime.UtcNow.AddSeconds(durationSec);
248 | 
249 |         while (DateTime.UtcNow < endTime && client.IsConnected)
250 |         {
251 |             try
252 |             {
253 |                 byte[] payload = Array.Empty<byte>();
254 |                 int delayMs;
255 | 
256 |                 switch (type)
257 |                 {
258 |                     case ClientType.ShortFast:
259 |                         // Small payload (64~256 bytes), fast send (10~30ms interval)
260 |                         var sizeA = 64 + rng.Next(0, 192);
261 |                         payload = GeneratePayload(sizeA, clientId, sendCount);
262 |                         delayMs = 10 + rng.Next(0, 20);
263 |                         break;
264 | 
265 |                     case ClientType.HeavyTransfer:
266 |                         // Large payload (512~4096 bytes), medium interval (50~150ms)
267 |                         var sizeB = 512 + rng.Next(0, 3584);
268 |                         payload = GeneratePayload(sizeB, clientId, sendCount);
269 |                         delayMs = 50 + rng.Next(0, 100);
270 |                         break;
271 | 
272 |                     case ClientType.Bursty:
273 |                         // Random bursts: either send 5~15 messages rapidly then idle, or single large
274 |                         if (rng.Next(0, 3) == 0)
275 |                         {
276 |                             // Burst mode
277 |                             for (int burst = 0; burst < rng.Next(5, 16); burst++)
278 |                             {
279 |                                 var sizeC = 64 + rng.Next(0, 2048);
280 |                                 payload = GeneratePayload(sizeC, clientId, sendCount);
281 |                                 await client.SendAsync(payload);
282 |                                 Interlocked.Add(ref bytesSentAccum, payload.Length);
283 |                                 stats.RecordPayloadSize(payload.Length);
284 |                                 sendCount++;
285 |                                 await Task.Delay(rng.Next(1, 5)); // very fast within burst
286 |                             }
287 |                             delayMs = 200 + rng.Next(0, 500); // long idle after burst
288 |                         }
289 |                         else
290 |                         {
291 |                             var sizeC = 128 + rng.Next(0, 1024);
292 |                             payload = GeneratePayload(sizeC, clientId, sendCount);
293 |                             delayMs = 30 + rng.Next(0, 200);
294 |                         }
295 |                         break;
296 | 
297 |                     default:
298 |                         var sizeD = 128;
299 |                         payload = GeneratePayload(sizeD, clientId, sendCount);
300 |                         delayMs = 50;
301 |                         break;
302 |                 }
303 | 
304 |                 if (type != ClientType.Bursty || rng.Next(0, 3) != 0)
305 |                 {
306 |                     await client.SendAsync(payload);
307 |                     Interlocked.Add(ref bytesSentAccum, payload.Length);
308 |                     stats.RecordPayloadSize(payload.Length);
309 |                     sendCount++;
310 |                 }
311 | 
312 |                 stats.RecordSendInterval(delayMs);
313 |                 await Task.Delay(delayMs);
314 |             }
