337 | static byte[] GeneratePayload(int size, int clientId, int msgSeq)
338 | {
339 |     // Deterministic but variable-content payload
340 |     var header = $"MSG:{clientId}:{msgSeq}:LEN={size}";
341 |     var headerBytes = Encoding.ASCII.GetBytes(header);
342 | 
343 |     var payload = new byte[size];
344 |     Buffer.BlockCopy(headerBytes, 0, payload, 0, Math.Min(headerBytes.Length, size));
345 | 
346 |     // Fill rest with repeating pattern based on client id & sequence
347 |     var fillByte = (byte)((clientId + msgSeq) % 256);
348 |     for (int i = Math.Min(headerBytes.Length, size); i < size; i++)
349 |         payload[i] = (byte)(fillByte + i % 10);
350 | 
351 |     return payload;
352 | }
