354 | static double Percentile(List<double> values, double percentile)
355 | {
356 |     if (values.Count == 0) return 0;
357 |     var list = values;
358 |     list.Sort();
359 |     int index = (int)Math.Ceiling(percentile / 100.0 * list.Count) - 1;
360 |     index = Math.Max(0, Math.Min(index, list.Count - 1));
361 |     return list[index];
362 | }
