sealed class Args
{
    public string Mode { get; set; } = "basic";
    public int NumClients { get; set; } = 100;
    public int DurationSec { get; set; } = 10;
    public string Host { get; set; } = "127.0.0.1";
    public int Port { get; set; } = 8080;
    public int BatchSize { get; set; } = 500;
    public int KillServerPort { get; set; } = 5002;

    public static Args Parse(string[] args)
    {
        var result = new Args();

        for (int i = 0; i < args.Length; i++)
        {
            var a = args[i].Trim().ToLowerInvariant();
            a switch
            {
                "basic" or "advanced" or "resilience" or "all" => result.Mode = a,
                "--clients" or "-c" => NumClients = int.Parse(args[++i]),
                "--duration" or "-d" => DurationSec = int.Parse(args[++i]),
                "--host" or "-h" => Host = args[++i],
                "--port" or "-p" => Port = int.Parse(args[++i]),
                "--batch" or "-b" => BatchSize = int.Parse(args[++i]),
                "--kill-port" or "-k" => KillServerPort = int.Parse(args[++i]),
                _ => { }
            };
        }

        // Override defaults per mode if not explicitly set
        // Basic mode defaults
        if (result.Mode == "basic")
        { result.NumClients = 100; result.DurationSec = 10; result.Port = 5000; }
        else if (result.Mode == "advanced")
        { result.NumClients = 10_000; result.DurationSec = 30; result.Port = 8080; }
        else if (result.Mode == "resilience")
        { result.NumClients = 100_000; result.DurationSec = 45; result.Port = 8080; result.BatchSize = 2000; }

        return result;
    }
}

