                            delayMs = 30 + rng.Next(0, 200);
                        }
                        if (rng.Next(0, 3) != 0)
                        {
                            await client.SendAsync(payload);
                            Interlocked.Add(ref sentBytes, payload.Length);
                            stats.RecordPayloadSize(payload.Length);
                            msgCount++;
                        }
                        break;
                    default:
                        payload = GenPayload(128, id, msgCount); delayMs = 50; break;
                }

                if (type != ClientType.Bursty || rng.Next(0, 3) != 0)
                { /* already handled in bursty case */ }
                else
                {
                    await client.SendAsync(payload);
                    Interlocked.Add(ref sentBytes, payload.Length);
                    stats.RecordPayloadSize(payload.Length);
                    msgCount++;
                }

                stats.RecordInterval(delayMs);
                await Task.Delay(delayMs);
            } catch { errCount++; }
        }

        result.MessagesSent = msgCount;
        result.BytesSent = sentBytes;
        result.BytesReceived = recvBytes;
        result.Errors = errCount;
    }
    catch (Exception ex) { result.ConnectSuccess = false; result.ErrorMessage = ex.Message; }
    return result;
}

