// ============================================================================
// SocketTests — Unified Test Framework
// ============================================================================
// Usage:
//   dotnet run --project SocketTests -- basic          [--clients 100]  [--duration 10]  [--host 127.0.0.1] [--port 8080]
//   dotnet run --project SocketTests -- advanced       [--clients 10000] [--duration 30] [--batch 500] ...
//   dotnet run --project SocketTests -- resilience     [--clients 100000] [--duration 45] [--batch 2000] [--kill-port 5002]
//   dotnet run --project SocketTests -- all            [--clients 1000] [--duration 10] ... (sequential: basic → advanced → resilience)
// ============================================================================

var args = Args.Parse(args);

if (args.Mode == "all")
{
    await RunAllTestsSequentially(args);
}
else
{
