// ============================================================================
// CLI Argument Parser
// ============================================================================

sealed class Args
{
    public string Mode { get; set; } = "basic";
    public int NumClients { get; set; } = 100;
    public int DurationSec { get; set; } = 10;
    public string Host { get; set; } = "127.0.0.1";
    public int Port { get; set; } = 8080;
    public int BatchSize { get; set; } = 500;
    public int KillServerPort { get; set; } = 5002;

    public static Args Parse(string[] rawArgs)
    {
        var result = new Args();

        for (int i = 0; i < rawArgs.Length; i++)
        {
            var a = rawArgs[i].Trim().ToLowerInvariant();
            a switch
            {
                "basic" or "advanced" or "resilience" or "all" => result.Mode = a,
                "--clients" or "-c" => result.NumClients = int.Parse(rawArgs[++i]),
                "--duration" or "-d" => result.DurationSec = int.Parse(rawArgs[++i]),
                "--host" or "-h" => result.Host = rawArgs[++i],
                "--port" or "-p" => result.Port = int.Parse(rawArgs[++i]),
                "--batch" or "-b" => result.BatchSize = int.Parse(rawArgs[++i]),
                "--kill-port" or "-k" => result.KillServerPort = int.Parse(rawArgs[++i]),
                _ => { }
            };
        }

        // Override defaults per mode if not explicitly set
        // Basic mode defaults
        if (result.Mode == "basic")
        { result.NumClients = 100; result.DurationSec = 10; result.Port = 5000; }
        else if (result.Mode == "advanced")
        { result.NumClients = 10_000; result.DurationSec = 30; result.Port = 8080; }
        else if (result.Mode == "resilience")
        { result.NumClients = 100_000; result.DurationSec = 45; result.Port = 8080; result.BatchSize = 2000; }

        return result;
    }
}

// ============================================================================
// Sequential Runner
// ============================================================================

static async Task RunAllTestsSequentially(Args cfg)
{
    var sep = new string('=', 80);
    Console.WriteLine(sep);
    Console.WriteLine("  RUNNING ALL TESTS SEQUENTIALLY");
    Console.WriteLine(sep);
    Console.WriteLine();

    // 1. Basic
    Console.WriteLine("[>>>] Starting BASIC test...");
    var basicCfg = new Args { Mode = "basic", NumClients = cfg.NumClients, DurationSec = cfg.DurationSec, Host = cfg.Host, Port = cfg.Port };
    await RunBasicTest(basicCfg);
    Console.WriteLine();
    Console.WriteLine("[OK]  BASIC test completed.\n");

    // 2. Advanced
    Console.WriteLine("[>>>] Starting ADVANCED test...");
    var advCfg = new Args { Mode = "advanced", NumClients = cfg.NumClients, DurationSec = cfg.DurationSec, Host = cfg.Host, Port = cfg.Port, BatchSize = cfg.BatchSize };
    await RunAdvancedTest(advCfg);
    Console.WriteLine();
    Console.WriteLine("[OK]  ADVANCED test completed.\n");

    // 3. Resilience (smaller scale for sequential run)
    Console.WriteLine("[>>>] Starting RESILIENCE test...");
    var resCfg = new Args { Mode = "resilience", NumClients = Math.Min(cfg.NumClients, 1000), DurationSec = cfg.DurationSec, Host = cfg.Host, Port = cfg.Port, BatchSize = cfg.BatchSize, KillServerPort = cfg.KillServerPort };
    await RunResilienceTest(resCfg);
    Console.WriteLine();
    Console.WriteLine("[OK]  RESILIENCE test completed.\n");

    Console.WriteLine(sep);
    Console.WriteLine("  ALL TESTS COMPLETED");
    Console.WriteLine(sep);
}

static async Task RunSingleTest(Args cfg)
{
    switch (cfg.Mode)
    {
        case "basic":
            await RunBasicTest(cfg);
