            Console.WriteLine($"[{sw.Elapsed.TotalSeconds:F1}s] Batch {b + 1}/{totalBatches}: launching {count} clients (#{startId}..#{startId + count - 1})");

            for (int i = startId; i < startId + count; i++)
            {
                var type = DetermineClientType(i, cfg.NumClients);
