            Console.WriteLine($"    P50 .......: {Percentile(times, 50):F2} ms");
            Console.WriteLine($"    P95 .......: {Percentile(times, 95):F2} ms");
            Console.WriteLine($"    P99 .......: {Percentile(times, 99):F2} ms");
