        Console.WriteLine("[>>>] Starting ADVANCED test...");
        await RunAdvancedTest(new Args { Mode = "advanced", NumClients = cfg.NumClients, DurationSec = cfg.DurationSec, Host = cfg.Host, Port = cfg.Port, BatchSize = cfg.BatchSize });
